begin;
set local search_path=public,extensions;
select plan(41);
update private.admin_execution_environment_v1 set environment='DEVELOPMENT',configuration_reference='ROLLBACK-ONLY-FISCAL-236'where singleton;
grant usage on schema extensions to authenticated;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select('f2360000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','fiscal236-'||i||'@example.invalid',now(),'{}','{}',now(),now()from generate_series(1,3)i;
insert into public.platform_user_roles(user_id,role_code)values('f2360000-0000-4000-8000-000000000001','FINANCE_MANAGER'),('f2360000-0000-4000-8000-000000000002','SUPER_ADMIN');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('f2361000-0000-4000-8000-000000000001','TEST fiscal236','TEST fiscal236','ACTIVE','f2360000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status)select('f2362000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'f2361000-0000-4000-8000-000000000001',('f2360000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'ACTIVE'from generate_series(1,2)i;
-- Historical published catalogue is a declared precondition. No fiscal decision is seeded.
insert into public.catalog_libraries(id,code,slug,steward_organization_id,created_by)values('f2363000-0000-4000-8000-000000000001','FISCAL236','fiscal236','f2361000-0000-4000-8000-000000000001','f2360000-0000-4000-8000-000000000001');
insert into public.catalog_categories(id,library_id,code,slug,created_by)values('f2363000-0000-4000-8000-000000000002','f2363000-0000-4000-8000-000000000001','FISCAL236_CAT','fiscal236-cat','f2360000-0000-4000-8000-000000000001');
insert into public.catalog_subcategories(id,library_id,category_id,code,slug,created_by)values('f2363000-0000-4000-8000-000000000003','f2363000-0000-4000-8000-000000000001','f2363000-0000-4000-8000-000000000002','FISCAL236_SUB','fiscal236-sub','f2360000-0000-4000-8000-000000000001');
insert into public.catalog_services(id,library_id,primary_subcategory_id,code,slug,created_by)values('f2363000-0000-4000-8000-000000000004','f2363000-0000-4000-8000-000000000001','f2363000-0000-4000-8000-000000000003','FISCAL236_SERVICE','fiscal236-service','f2360000-0000-4000-8000-000000000001');
insert into public.catalog_service_versions(id,service_id,library_id,version,status,name_fr,name_ar,short_description_fr,short_description_ar,long_description_fr,long_description_ar,service_type,unit_label_fr,unit_label_ar,sort_order,change_reason,content_hash,created_by,published_at)values('f2363000-0000-4000-8000-000000000005','f2363000-0000-4000-8000-000000000004','f2363000-0000-4000-8000-000000000001',1,'PUBLISHED','Service fiscal TEST','خدمة اختبار','Service test','خدمة اختبار','Service catalogue historique TEST','خدمة اختبار تاريخية','CONSULTING','Forfait','حزمة',1,'Historical published catalogue fixture',repeat('6',64),'f2360000-0000-4000-8000-000000000001',now()-interval'2 days');
insert into public.tax_categories(code,name_fr,name_ar,description_fr,description_ar,category_kind,status)values('TEST_FISCAL236','Taxe TEST','ضريبة اختبار','Catégorie synthétique TEST','فئة اختبار','SERVICE','ACTIVE');
create temporary table results(k text primary key,v jsonb);grant all on results to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f2360000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.list_service_tax_category_sources_v1()$$,'42501','SERVICE_TAX_FINANCE_AAL2_REQUIRED','foreign actor cannot browse finance registry');
select set_config('request.jwt.claims','{"sub":"f2360000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.list_service_tax_category_sources_v1()$$,'42501','SERVICE_TAX_FINANCE_AAL2_REQUIRED','finance requires real AAL2');
select set_config('request.jwt.claims','{"sub":"f2360000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select is((public.list_service_tax_category_sources_v1('FISCAL236')->'items'->0->>'id'),'f2363000-0000-4000-8000-000000000005','operator finds exact published service version');
insert into results values('context',public.get_service_tax_category_mapping_context_v1('f2363000-0000-4000-8000-000000000005','MA','MAD'));
select throws_ok($$select public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',current_date)$$,'55000','SERVICE_TAX_CATEGORY_POLICY_REQUIRED','no category default exists');
insert into results values('rule',public.propose_morocco_tax_rule('f2361000-0000-4000-8000-000000000001','TEST_FISCAL236','VAT',2000,1,'{}','TEST synthetic tax rule, not legal approval',current_date-2,null,'TEST independent tax engine validation','fiscal236-rule'));
insert into results values('proposal',public.propose_service_tax_category_mapping_v1('f2363000-0000-4000-8000-000000000005',repeat('6',64),(select v->>'scope_hash'from results where k='context'),'MA','MAD','TEST_FISCAL236',current_date,null,true,'{}','TEST dated service association','f2364000-0000-4000-8000-000000000001'));
select is((select v->>'outcome'from results where k='proposal'),'SERVICE_TAX_MAPPING_PROPOSED','finance proposes immutable exact-source classification');
select is(public.propose_service_tax_category_mapping_v1('f2363000-0000-4000-8000-000000000005',repeat('6',64),(select v->>'scope_hash'from results where k='context'),'MA','MAD','TEST_FISCAL236',current_date,null,true,'{}','TEST dated service association','f2364000-0000-4000-8000-000000000001'),(select v from results where k='proposal'),'proposal replay is exact');
select throws_ok($$select public.decide_service_tax_category_mapping_v1((select(v->>'proposal_id')::uuid from results where k='proposal'),(select v->>'content_hash'from results where k='proposal'),true,'TEST/236','Independent TEST fiscal approval')$$,'42501','FOUR_EYES_REQUIRED','author cannot publish own classification');
select set_config('request.jwt.claims','{"sub":"f2360000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.decide_service_tax_category_mapping_v1((select(v->>'proposal_id')::uuid from results where k='proposal'),repeat('f',64),true,'TEST/236','Independent TEST fiscal approval')$$,'40001','SERVICE_TAX_PROPOSAL_CHANGED','review is bound to exact proposal hash');
select throws_ok($$select public.decide_service_tax_category_mapping_v1((select(v->>'proposal_id')::uuid from results where k='proposal'),(select v->>'content_hash'from results where k='proposal'),true,'TEST/236','Independent TEST fiscal approval')$$,'55000','SERVICE_TAX_RULE_REQUIRED','classification cannot publish without validated dated tax rule');
select is((public.decide_morocco_tax_rule('f2361000-0000-4000-8000-000000000001',(select(v->>'tax_rule_version_id')::uuid from results where k='rule'),'APPROVE','VALIDATED','TEST/236/RULE','Independent synthetic fiscal validation',1,'fiscal236-rule-approval')->>'outcome'),'MOROCCO_TAX_RULE_ACTIVATED','existing engine rule approved by distinct real actor');
insert into results values('approved',public.decide_service_tax_category_mapping_v1((select(v->>'proposal_id')::uuid from results where k='proposal'),(select v->>'content_hash'from results where k='proposal'),true,'TEST/236','Independent TEST fiscal approval'));
select is((select v->>'outcome'from results where k='approved'),'SERVICE_TAX_MAPPING_PUBLISHED','independent finance reviewer publishes classification');
select is(public.decide_service_tax_category_mapping_v1((select(v->>'proposal_id')::uuid from results where k='proposal'),(select v->>'content_hash'from results where k='proposal'),true,'TEST/236','Independent TEST fiscal approval'),(select v from results where k='approved'),'lost approval reply replays exact document');
insert into results values('resolved',public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',current_date));
select is((select v->>'category_code'from results where k='resolved'),'TEST_FISCAL236','canonical getter returns reviewed category');
select is((select v->>'service_content_hash'from results where k='resolved'),repeat('6',64),'resolved snapshot is pinned to service content hash');
select is((select v->>'mapping_id'from results where k='resolved'),(select v->>'mapping_id'from results where k='approved'),'getter binds exact approval');
select throws_ok($$select public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','MA','EUR',current_date)$$,'55000','SERVICE_TAX_CATEGORY_POLICY_REQUIRED','currency scopes never fall back');
select throws_ok($$select public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','FR','MAD',current_date)$$,'55000','SERVICE_TAX_JURISDICTION_UNSUPPORTED','unsupported jurisdiction never inherits Morocco');
select throws_ok($$select public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',current_date-1)$$,'55000','SERVICE_TAX_CATEGORY_POLICY_REQUIRED','effective date cannot use a future mapping');
select set_config('request.jwt.claims','{"sub":"f2360000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.propose_service_tax_category_mapping_v1('f2363000-0000-4000-8000-000000000005',repeat('f',64),(select v->>'scope_hash'from results where k='context'),'MA','MAD','TEST_FISCAL236',current_date,null,true,'{}','TEST stale source classification','f2364000-0000-4000-8000-000000000002')$$,'40001','SERVICE_TAX_SOURCE_CHANGED','stale source hash cannot create new proposal');
select throws_ok($$select public.propose_service_tax_category_mapping_v1('f2363000-0000-4000-8000-000000000005',repeat('6',64),(select v->>'scope_hash'from results where k='context'),'MA','MAD','TEST_FISCAL236',current_date,null,true,'{}','TEST stale scope classification','f2364000-0000-4000-8000-000000000002')$$,'40001','SERVICE_TAX_SCOPE_CHANGED','stale scope hash cannot hide a concurrent mapping');
reset role;
select throws_ok($$update public.service_tax_category_mappings set category_code='TEST_FISCAL236'where id=(select(v->>'mapping_id')::uuid from results where k='approved')$$,'55000',null,'published mappings are immutable even for table owner');
select ok(not has_table_privilege('authenticated','public.service_tax_category_mappings','INSERT'),'users cannot inject approved mappings');
select ok(not has_function_privilege('authenticated','private.resolve_service_tax_category_v1(uuid,text,character,date)','EXECUTE'),'canonical helper is private');
select ok(not has_function_privilege('anon','public.get_service_tax_category_policy_v1(uuid,text,character,date)','EXECUTE'),'anonymous policy access is denied');
update private.admin_execution_environment_v1 set environment='PRODUCTION'where singleton;
select throws_ok($$select private.resolve_service_tax_category_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',current_date)$$,'55000','SERVICE_TAX_CATEGORY_POLICY_REQUIRED','development mapping cannot cross deployment boundary');
update private.admin_execution_environment_v1 set environment='DEVELOPMENT'where singleton;
select is((select count(*)from public.service_tax_category_mappings),1::bigint,'failed decisions never publish partial mappings');
select is((select count(*)from public.service_tax_mapping_decisions),1::bigint,'failed review before tax rule leaves no decision record');
select ok(exists(select 1 from public.audit_events where action='tax.service_mapping.approved'and resource_id=(select v->>'mapping_id'from results where k='approved')),'approval has durable audit evidence');
select is((public.get_service_tax_category_mapping_context_v1('f2363000-0000-4000-8000-000000000005','MA','MAD')->'proposals'->0->>'decision'),'APPROVED','operator sees actual persisted decision');
-- Review the exact overlap set. A finite replacement must never resurrect the old mapping.
insert into results values('context2',public.get_service_tax_category_mapping_context_v1('f2363000-0000-4000-8000-000000000005','MA','MAD'));
insert into results values('unreviewedOverlap',public.propose_service_tax_category_mapping_v1('f2363000-0000-4000-8000-000000000005',repeat('6',64),(select v->>'scope_hash'from results where k='context2'),'MA','MAD','TEST_FISCAL236',current_date+1,current_date+3,true,'{}','TEST overlap not explicitly reviewed','f2364000-0000-4000-8000-000000000003'));
select set_config('request.jwt.claims','{"sub":"f2360000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.decide_service_tax_category_mapping_v1((select(v->>'proposal_id')::uuid from results where k='unreviewedOverlap'),(select v->>'content_hash'from results where k='unreviewedOverlap'),true,'TEST/236/OVERLAP','Independent overlap validation')$$,'55000','SERVICE_TAX_SUPERSESSION_REVIEW_REQUIRED','overlap requires explicit replacement review');
select set_config('request.jwt.claims','{"sub":"f2360000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into results values('replacement',public.propose_service_tax_category_mapping_v1('f2363000-0000-4000-8000-000000000005',repeat('6',64),(select v->>'scope_hash'from results where k='context2'),'MA','MAD','TEST_FISCAL236',current_date+1,current_date+3,true,array[(select(v->>'mapping_id')::uuid from results where k='approved')],'TEST finite reviewed replacement','f2364000-0000-4000-8000-000000000004'));
select set_config('request.jwt.claims','{"sub":"f2360000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into results values('replacementApproved',public.decide_service_tax_category_mapping_v1((select(v->>'proposal_id')::uuid from results where k='replacement'),(select v->>'content_hash'from results where k='replacement'),true,'TEST/236/REPLACE','Independent finite replacement approval'));
select is((select v->>'outcome'from results where k='replacementApproved'),'SERVICE_TAX_MAPPING_PUBLISHED','explicit overlap set is published atomically');
select is((public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',current_date)->>'mapping_id'),(select v->>'mapping_id'from results where k='approved'),'original date retains its immutable policy');
select is((public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',current_date+1)->>'mapping_id'),(select v->>'mapping_id'from results where k='replacementApproved'),'replacement begins on exact inclusive boundary');
select is((public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',current_date+3)->>'mapping_id'),(select v->>'mapping_id'from results where k='replacementApproved'),'replacement final day remains included');
select throws_ok($$select public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',current_date+4)$$,'55000','SERVICE_TAX_CATEGORY_POLICY_REQUIRED','finite replacement does not resurrect superseded policy');
select throws_ok($$select public.decide_service_tax_category_mapping_v1((select(v->>'proposal_id')::uuid from results where k='unreviewedOverlap'),(select v->>'content_hash'from results where k='unreviewedOverlap'),true,'TEST/236/STALE','Independent stale review refused')$$,'40001','SERVICE_TAX_SCOPE_CHANGED','concurrent publication invalidates an older undecided context');
select throws_ok($$select public.get_service_tax_category_policy_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',null)$$,'22023','INVALID_SERVICE_TAX_SCOPE','NULL effective date cannot bypass dated resolution');
select throws_ok($$select public.get_service_tax_category_mapping_context_v1('f2363000-0000-4000-8000-000000000005','MA','MAD',null)$$,'22023','INVALID_SERVICE_TAX_SCOPE','NULL page cannot bypass history bounds');
select is((select count(*)from public.service_tax_mapping_supersessions where mapping_id=(select(v->>'mapping_id')::uuid from results where k='approved')),1::bigint,'replacement records immutable lineage');
select is((select content_hash from public.service_tax_category_mappings where id=(select(v->>'mapping_id')::uuid from results where k='approved')),(select v->>'content_hash'from results where k='approved'),'original policy hash remains unchanged');
select ok(not has_table_privilege('service_role','public.service_tax_mapping_decisions','INSERT'),'service transport cannot fabricate fiscal approval');
select *from finish();
rollback;
